import{_ as l,l as r,o as e,c as i,v as o,p as n,x as t,d as B,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"Tomasulo","description":"","frontmatter":{"title":"Tomasulo","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tomasulo.md","filePath":"cs/tomasulo.md","lastUpdated":1789023840000}'),p={name:"cs/tomasulo.md"};function E(u,a,c,A,h,_){const s=r("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="tomasulo" tabindex="-1">Tomasulo <a class="header-anchor" href="#tomasulo" aria-label="Permalink to &quot;Tomasulo&quot;">​</a></h1><div class="epigraph"><p>保留站记下谁在等哪次运算的结果，公共数据总线一广播标签，等待者自己抓住数据。</p><footer>—— 据 Tomasulo, An Efficient Algorithm for Exploiting Multiple Arithmetic Units, IBM Journal 1967 整理</footer></div><p><a href="/cs/ooo-rob">上一课</a>规定了 ROB 与按序提交，并把重命名说成「必须有」。本课不重讲提交纪律。缺口是：还没有一套具体的唤醒与分发机制，让「操作数就绪」变成硬件能做的比较。本课只讲 Tomasulo：保留站、标签、CDB。IBM System/360 Model 91 的浮点单元是原文场景；整数乱序核沿用同一思想。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ROB 知道指令完成没有，但功能单元怎么发现操作数到了？轮询架构寄存器不够：值可能还在另一单元的输出上，且寄存器已被重命名。缺口不是再加一个提交点，而是<strong>用标签代替寄存器名做数据流握手</strong>。</p><p>Tomasulo 原论文为多运算单元与长延迟浮点而写，尚未画现代 ROB；教学上把保留站与 ROB 叠在一起：站负责执行，ROB 负责精确状态。</p><p><span class="marginnote">1967 年的 CDB 是广播总线。当代核用点对点与唤醒矩阵，语义仍是「标签匹配则抓数据」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每条已发射未执行的指令占用一个保留站：存操作码、操作数或「等待的标签」、目标标签。寄存器状态表指出：该架构寄存器的当前生产者是哪一个标签（或值已在寄存器）。运算完成，结果带标签上 CDB；所有站比较标签，匹配则写入操作数并可能变为就绪。</p>',9)),(e(),n(m,null,{default:t(()=>[d(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20IS%5B%22%E5%8F%91%E5%B0%84%E5%88%B0%E4%BF%9D%E7%95%99%E7%AB%99%22%5D%20--%3E%20WAIT%5B%22%E7%AD%89%E6%A0%87%E7%AD%BE%E6%88%96%E5%B7%B2%E6%9C%89%E5%80%BC%22%5D%0A%20%20WAIT%20--%3E%20EX%5B%22%E4%B8%A4%E6%93%8D%E4%BD%9C%E6%95%B0%E9%BD%90%E5%88%99%E8%BF%90%E7%AE%97%22%5D%0A%20%20EX%20--%3E%20CDB%5B%22CDB%20%E5%B9%BF%E6%92%AD%E7%BB%93%E6%9E%9C%2B%E6%A0%87%E7%AD%BE%22%5D%0A%20%20CDB%20--%3E%20WAIT%0A%20%20CDB%20--%3E%20RF%5B%22%E5%86%99%E5%AF%84%E5%AD%98%E5%99%A8%2FROB%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>load/store 另有地址序约束，原文用缓冲。本课只要求：RAW 靠标签，WAR/WAW 靠「后来的发射改状态表指向新标签」，旧站仍拿旧标签。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>这就是数据流：指令不按程序序被挑选，按操作数齐被挑选。与 ROB 结合后，CDB 写 ROB 项，提交仍按头指针。<a href="/cs/superscalar-issue">超标量发射</a>的宽度变成每拍能填几个站、CDB 能广播几次。</p><p>精确异常：冲刷时作废站与标签，状态表回到 ROB 头对应的映射。Tomasulo 原文更关心吞吐而非陷阱；当代实现把两者接上。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把记分牌当成另一套主干：记分牌跟踪忙位但不做标签重命名，WAW 要停。也不引入负载值预测。SIMD 与多核不在本课；Tomasulo 解决的是单核 ILP 的唤醒。</p><p>后课默认：谈到乱序唤醒，就是标签匹配。下一条路是数据级并行：一条指令吃一个向量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>保留站 + 标签 + CDB：就绪即执行，RAW 靠匹配。</li><li>与 ROB 叠放才有精确提交。</li><li>向量/SIMD 是另一轴并行，下一课才走。</li><li>出处：Tomasulo, <em>IBM Journal of Research and Development</em>, 1967；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',9))])}const f=l(p,[["render",E]]);export{T as __pageData,f as default};
